import React, { useState, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Bell, Search, Menu, User, Settings, LogOut } from 'lucide-react';

const TopBar = ({ toggleSidebar, toggleDarkMode, darkMode }) => {
  const [showNotifications, setShowNotifications] = useState(false);
  const [showUserMenu, setShowUserMenu] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [notifications, setNotifications] = useState([]);
  const navigate = useNavigate();
  const location = useLocation();

  // Charger les notifications au démarrage
  useEffect(() => {
    // Simuler des notifications (à remplacer par votre API)
    const mockNotifications = [
      { id: 1, title: 'Nouveau message', message: 'Vous avez reçu un nouveau message', time: 'Il y a 5 min', read: false, type: 'message' },
      { id: 2, title: 'Commande validée', message: 'Commande #12345 a été validée', time: 'Il y a 30 min', read: false, type: 'order' },
      { id: 3, title: 'Nouvel utilisateur', message: 'Un nouvel utilisateur s\'est inscrit', time: 'Il y a 2h', read: true, type: 'user' },
      { id: 4, title: 'Mise à jour système', message: 'Mise à jour disponible', time: 'Hier', read: true, type: 'system' },
    ];
    setNotifications(mockNotifications);
  }, []);

  // Fonction pour basculer le mode sombre
  const handleToggleDarkMode = () => {
    toggleDarkMode();
    // Sauvegarder la préférence dans localStorage
    localStorage.setItem('darkMode', !darkMode);
  };

  // Fonction pour marquer toutes les notifications comme lues
  const markAllAsRead = () => {
    setNotifications(notifications.map(notif => ({ ...notif, read: true })));
    setShowNotifications(false);
  };

  // Fonction pour supprimer une notification
  const handleDeleteNotification = (id) => {
    setNotifications(notifications.filter(notif => notif.id !== id));
  };

  // Fonction pour gérer la recherche
  const handleSearch = (e) => {
    e.preventDefault();
    if (searchQuery.trim()) {
      console.log('Recherche:', searchQuery);
      // Implémentez votre logique de recherche ici
    }
  };

  // Fonction pour obtenir l'icône selon le type de notification
  const getNotificationIcon = (type) => {
    switch (type) {
      case 'message': return '💬';
      case 'order': return '📦';
      case 'user': return '👤';
      case 'system': return '⚙️';
      default: return '🔔';
    }
  };

  // Fonction pour obtenir la couleur selon le type de notification
  const getNotificationColor = (type) => {
    switch (type) {
      case 'message': return 'bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400';
      case 'order': return 'bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400';
      case 'user': return 'bg-purple-100 dark:bg-purple-900/30 text-purple-600 dark:text-purple-400';
      case 'system': return 'bg-amber-100 dark:bg-amber-900/30 text-amber-600 dark:text-amber-400';
      default: return 'bg-neutral-100 dark:bg-neutral-800 text-neutral-600 dark:text-neutral-400';
    }
  };

  // Fonction pour gérer le clic sur une notification
  const handleNotificationClick = (notification) => {
    if (!notification.read) {
      setNotifications(notifications.map(notif => 
        notif.id === notification.id ? { ...notif, read: true } : notif
      ));
    }

    // Naviguer selon le type de notification
    switch (notification.type) {
      case 'message':
        navigate('/dashboard/messages');
        break;
      case 'order':
        navigate('/dashboard/orders');
        break;
      case 'user':
        navigate('/dashboard/users');
        break;
      default:
        break;
    }

    setShowNotifications(false);
  };

  // Fonction pour déconnexion
  const handleLogout = () => {
    localStorage.removeItem('authToken');
    localStorage.removeItem('userData');
    navigate('/login');
    setShowUserMenu(false);
  };

  const getPageTitle = () => {
    const path = location.pathname;

    const pageTitles = {
      '/dashboard': 'Tableau de bord',
      '/dashboard/users': 'Gestion des utilisateurs',
      '/dashboard/products': 'Gestion des produits',
      '/dashboard/orders': 'Commandes',
      '/dashboard/analytics': 'Analytique',
      '/dashboard/messages': 'Messages',
      '/dashboard/settings': 'Paramètres',
      '/dashboard/reports': 'Rapports',
      '/dashboard/calendar': 'Calendrier',
      '/dashboard/notifications': 'Notifications',
      '/dashboard/system': 'Système',
      '/dashboard/database': 'Base de données',
      '/dashboard/backup': 'Sauvegarde',
    };

    return pageTitles[path] || 'Tableau de bord';
  };

  const getBreadcrumbs = () => {
    const path = location.pathname;
    const segments = path.split('/').filter(segment => segment);

    if (segments.length === 0) return ['Tableau de bord'];

    const breadcrumbMap = {
      'dashboard': 'Tableau de bord',
      'users': 'Utilisateurs',
      'products': 'Produits',
      'orders': 'Commandes',
      'analytics': 'Analytique',
      'messages': 'Messages',
      'settings': 'Paramètres',
      'reports': 'Rapports',
      'calendar': 'Calendrier',
      'notifications': 'Notifications',
      'system': 'Système',
      'database': 'Base de données',
      'backup': 'Sauvegarde',
    };

    return segments.map(segment => breadcrumbMap[segment] || segment);
  };

  const pageTitle = getPageTitle();
  const breadcrumbs = getBreadcrumbs();
  const unreadCount = notifications.filter(notif => !notif.read).length;

  return (
    <header className="sticky top-0 z-50 bg-white/90 dark:bg-neutral-900/90 backdrop-blur-xl border-b border-neutral-200/50 dark:border-neutral-800/50">
      <div className="px-6 py-4">
        <div className="flex items-center justify-between">
          {/* Left side */}
          <div className="flex items-center space-x-4">
            <button
              onClick={toggleSidebar}
              className="lg:hidden p-2 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors"
              aria-label="Toggle sidebar"
            >
              <Menu className="h-5 w-5 text-neutral-700 dark:text-neutral-300" />
            </button>

            <div>
              <h1 className="text-xl font-bold text-neutral-900 dark:text-white">
                {pageTitle}
              </h1>
              <div className="flex items-center space-x-2 text-sm text-neutral-500 dark:text-neutral-400">
                {breadcrumbs.map((crumb, index) => (
                  <React.Fragment key={index}>
                    <span>{crumb}</span>
                    {index < breadcrumbs.length - 1 && (
                      <span className="text-neutral-300 dark:text-neutral-600">/</span>
                    )}
                  </React.Fragment>
                ))}
              </div>
            </div>
          </div>

          {/* Right side */}
          <div className="flex items-center space-x-3">
            {/* Search */}
            <form onSubmit={handleSearch} className="relative hidden md:block">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-neutral-400" />
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Rechercher..."
                className="pl-10 pr-4 py-2 w-64 rounded-xl bg-neutral-100 dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent text-neutral-900 dark:text-white placeholder-neutral-500"
              />
            </form>

            {/* Notifications */}
            <div className="relative">
              <button
                onClick={() => setShowNotifications(!showNotifications)}
                className="relative p-2 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors"
                aria-label="Notifications"
              >
                <Bell className="h-5 w-5 text-neutral-700 dark:text-neutral-300" />
                {unreadCount > 0 && (
                  <span className="absolute -top-1 -right-1 h-5 w-5 bg-red-500 text-white text-xs rounded-full flex items-center justify-center animate-pulse">
                    {unreadCount}
                  </span>
                )}
              </button>

              {/* Dropdown Notifications */}
              {showNotifications && (
                <>
                  {/* Overlay pour fermer en cliquant à côté */}
                  <div 
                    className="fixed inset-0 z-40" 
                    onClick={() => setShowNotifications(false)}
                  />

                  <div className="absolute right-0 mt-2 w-80 bg-white dark:bg-neutral-800 rounded-xl shadow-2xl border border-neutral-200 dark:border-neutral-700 z-50">
                    <div className="p-4 border-b border-neutral-200 dark:border-neutral-700">
                      <div className="flex items-center justify-between">
                        <h3 className="font-semibold text-neutral-900 dark:text-white">
                          Notifications
                        </h3>
                        {unreadCount > 0 && (
                          <button
                            onClick={markAllAsRead}
                            className="text-xs text-primary-600 dark:text-primary-400 hover:underline"
                          >
                            Tout marquer comme lu
                          </button>
                        )}
                      </div>
                    </div>

                    <div className="max-h-96 overflow-y-auto">
                      {notifications.length === 0 ? (
                        <div className="p-6 text-center">
                          <Bell className="h-12 w-12 text-neutral-400 mx-auto mb-3" />
                          <p className="text-neutral-500 dark:text-neutral-400">
                            Aucune notification
                          </p>
                        </div>
                      ) : (
                        <div className="divide-y divide-neutral-100 dark:divide-neutral-700">
                          {notifications.map(notification => (
                            <div
                              key={notification.id}
                              onClick={() => handleNotificationClick(notification)}
                              className={`p-4 cursor-pointer hover:bg-neutral-50 dark:hover:bg-neutral-700/50 transition-colors ${
                                !notification.read ? 'bg-blue-50/50 dark:bg-blue-900/10' : ''
                              }`}
                            >
                              <div className="flex items-start gap-3">
                                <div className={`h-10 w-10 rounded-full ${getNotificationColor(notification.type)} flex items-center justify-center text-lg`}>
                                  {getNotificationIcon(notification.type)}
                                </div>
                                <div className="flex-1 min-w-0">
                                  <div className="flex items-center justify-between mb-1">
                                    <h4 className="font-medium text-sm text-neutral-900 dark:text-white truncate">
                                      {notification.title}
                                    </h4>
                                    <button
                                      onClick={(e) => {
                                        e.stopPropagation();
                                        handleDeleteNotification(notification.id);
                                      }}
                                      className="text-xs text-neutral-400 hover:text-red-500"
                                    >
                                      ×
                                    </button>
                                  </div>
                                  <p className="text-xs text-neutral-600 dark:text-neutral-300 mb-1">
                                    {notification.message}
                                  </p>
                                  <div className="flex items-center justify-between">
                                    <span className="text-xs text-neutral-500">
                                      {notification.time}
                                    </span>
                                    {!notification.read && (
                                      <span className="h-2 w-2 rounded-full bg-blue-500"></span>
                                    )}
                                  </div>
                                </div>
                              </div>
                            </div>
                          ))}
                        </div>
                      )}
                    </div>

                    <div className="p-3 border-t border-neutral-200 dark:border-neutral-700">
                      <button
                        onClick={() => {
                          navigate('/dashboard/notifications');
                          setShowNotifications(false);
                        }}
                        className="w-full py-2 text-sm text-primary-600 dark:text-primary-400 hover:bg-neutral-50 dark:hover:bg-neutral-700 rounded-lg transition-colors"
                      >
                        Voir toutes les notifications
                      </button>
                    </div>
                  </div>
                </>
              )}
            </div>

            {/* User Menu */}
            <div className="relative">
              <button
                onClick={() => setShowUserMenu(!showUserMenu)}
                className="flex items-center space-x-3 pl-3 border-l border-neutral-200 dark:border-neutral-800 hover:opacity-80 transition-opacity"
              >
                <div className="h-8 w-8 rounded-full bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center shadow-lg">
                  <User className="h-4 w-4 text-white" />
                </div>
                <div className="hidden md:block text-left">
                  <p className="text-sm font-medium text-neutral-900 dark:text-white">
                    Enzo Admin
                  </p>
                  <p className="text-xs text-neutral-500 dark:text-neutral-400">
                    Administrateur
                  </p>
                </div>
              </button>

              {/* Dropdown User Menu */}
              {showUserMenu && (
                <>
                  <div 
                    className="fixed inset-0 z-40" 
                    onClick={() => setShowUserMenu(false)}
                  />

                  <div className="absolute right-0 mt-2 w-48 bg-white dark:bg-neutral-800 rounded-xl shadow-2xl border border-neutral-200 dark:border-neutral-700 z-50">
                    <div className="p-4 border-b border-neutral-200 dark:border-neutral-700">
                      <p className="font-medium text-neutral-900 dark:text-white">
                        Enzo Admin
                      </p>
                      <p className="text-xs text-neutral-500 dark:text-neutral-400">
                        enzo@gmail.com
                      </p>
                    </div>

                    <div className="p-2">
                      <button
                        onClick={() => {
                          navigate('/dashboard/settings');
                          setShowUserMenu(false);
                        }}
                        className="w-full px-3 py-2 text-sm text-left rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-700 flex items-center gap-2 transition-colors"
                      >
                        <Settings className="h-4 w-4" />
                        Paramètres
                      </button>

                      <button
                        onClick={handleLogout}
                        className="w-full px-3 py-2 text-sm text-left rounded-lg hover:bg-red-50 dark:hover:bg-red-900/20 text-red-500 flex items-center gap-2 transition-colors mt-1"
                      >
                        <LogOut className="h-4 w-4" />
                        Déconnexion
                      </button>
                    </div>
                  </div>
                </>
              )}
            </div>
          </div>
        </div>
      </div>
    </header>
  );
};

export default TopBar;
